"use client"

import * as React from "react"
import { CircleAlert } from "lucide-react"
import { cn } from "@/lib/utils"
import { Info } from "@/registry/jim/ui/info"

type FieldCtx = { id: string; describedBy?: string; invalid: boolean; required: boolean }
const FieldContext = React.createContext<FieldCtx | null>(null)

/** Inputs inside a Field pick up id, aria-describedby, aria-invalid, required. */
export function useFieldControl() {
  const ctx = React.useContext(FieldContext)
  if (!ctx) return {}
  return {
    id: ctx.id,
    "aria-describedby": ctx.describedBy,
    "aria-invalid": ctx.invalid || undefined,
    "aria-required": ctx.required || undefined,
  }
}

/** Wire a control the same way Field does, for layouts that place their own label (DetailList). */
export function FieldControlProvider({
  id,
  describedBy,
  invalid = false,
  required = false,
  children,
}: {
  id: string
  describedBy?: string
  invalid?: boolean
  required?: boolean
  children: React.ReactNode
}) {
  return <FieldContext.Provider value={{ id, describedBy, invalid, required }}>{children}</FieldContext.Provider>
}

/**
 * Label on top, control, then one line below: the error if there is one,
 * otherwise a short hint. Longer explanations go behind the ⓘ (`info`),
 * not as permanent text.
 */
export function Field({
  label,
  required,
  hint,
  info,
  error,
  id: idProp,
  className,
  children,
}: {
  label: React.ReactNode
  required?: boolean
  hint?: React.ReactNode
  info?: React.ReactNode
  error?: React.ReactNode
  id?: string
  className?: string
  children: React.ReactNode
}) {
  const auto = React.useId()
  const id = idProp ?? auto
  const noteId = `${id}-note`
  const note = error ?? hint
  return (
    <FieldContext.Provider value={{ id, describedBy: note ? noteId : undefined, invalid: !!error, required: !!required }}>
      <div data-slot="field" className={cn("flex flex-col gap-1.5", className)}>
        <div className="flex items-center gap-1">
          <label id={`${id}-label`} htmlFor={id} className="text-small font-medium text-foreground">
            {label}
            {required && (
              <span className="ml-0.5 text-destructive" aria-hidden>
                *
              </span>
            )}
          </label>
          {info && <Info>{info}</Info>}
        </div>
        {children}
        {note && !error && (
          <p id={noteId} className="flex items-start gap-1 text-caption text-faint-foreground">
            <span>{note}</span>
          </p>
        )}
        {/* Always mounted so a new error is announced; sr-only (out of flow, no gap) while empty. */}
        <p
          id={error ? noteId : undefined}
          aria-live="polite"
          className={error ? "flex items-start gap-1 text-caption text-destructive" : "sr-only"}
        >
          {error && (
            <>
              <CircleAlert className="mt-0.5 size-3.5" />
              <span>{error}</span>
            </>
          )}
        </p>
      </div>
    </FieldContext.Provider>
  )
}

/** Vertical stack of fields; --space-field (16) between fields, --space-section (32) between groups. */
export function FieldGroup({ className, ...props }: React.ComponentProps<"div">) {
  return <div className={cn("flex flex-col gap-(--space-field)", className)} {...props} />
}
